from typing import Dict

def count_vowels(text: str) -> Dict[str, int]:
    """Count occurrences of each vowel in the input string.

    Args:
        text: The input string; may contain any characters.

    Returns:
        A dict mapping each vowel 'a', 'e', 'i', 'o', 'u' to its count.
        Vowels absent from the string map to 0.

    Examples:
        >>> count_vowels("Hello World")
        {'a': 0, 'e': 1, 'i': 0, 'o': 2, 'u': 0}
        >>> count_vowels("")
        {'a': 0, 'e': 0, 'i': 0, 'o': 0, 'u': 0}
    """
    if not isinstance(text, str):
        raise TypeError("text must be a str")
    counts: Dict[str, int] = {"a": 0, "e": 0, "i": 0, "o": 0, "u": 0}
    for ch in text.lower():
        if ch in counts:
            counts[ch] += 1
    return counts

from typing import Dict, Any

def flatten_dict(d: Dict[Any, Any], parent_key: str = "") -> Dict[str, Any]:
    """Flatten a nested dict into dot-separated keys.

    Args:
        d: The dictionary to flatten.
        parent_key: Accumulated key prefix (used internally).

    Returns:
        A flat dict where nested keys are joined with '.'.

    Examples:
        >>> flatten_dict({"a": {"b": 1, "c": {"d": 2}}})
        {'a.b': 1, 'a.c.d': 2}
        >>> flatten_dict({"x": 5})
        {'x': 5}
    """
    if not isinstance(d, dict):
        raise TypeError("d must be a dict")
    out: Dict[str, Any] = {}
    for k, v in d.items():
        key = f"{parent_key}.{k}" if parent_key else str(k)
        if isinstance(v, dict):
            out.update(flatten_dict(v, key))
        else:
            out[key] = v
    return out

from typing import Any, List

class StackEmptyError(Exception):
    """Raised when an operation requires a non-empty stack."""
    pass

class Stack:
    """A simple LIFO stack implemented on top of a Python list.

    Examples:
        >>> s = Stack()
        >>> s.push(1)
        >>> s.push(2)
        >>> s.pop()
        2
        >>> s.peek()
        1
        >>> s.is_empty()
        False
    """
    def __init__(self) -> None:
        self._data: List[Any] = []

    def push(self, item: Any) -> None:
        self._data.append(item)

    def pop(self) -> Any:
        if not self._data:
            raise StackEmptyError("pop from empty stack")
        return self._data.pop()

    def peek(self) -> Any:
        if not self._data:
            raise StackEmptyError("peek from empty stack")
        return self._data[-1]

    def is_empty(self) -> bool:
        return not self._data

    def size(self) -> int:
        return len(self._data)

from typing import Any, List

class QueueEmptyError(Exception):
    """Raised when dequeue is attempted on an empty queue."""
    pass

class TwoStackQueue:
    """A FIFO queue implemented with two stacks.

    Examples:
        >>> q = TwoStackQueue()
        >>> q.enqueue(1)
        >>> q.enqueue(2)
        >>> q.dequeue()
        1
        >>> q.dequeue()
        2
    """
    def __init__(self) -> None:
        self._inbox: List[Any] = []
        self._outbox: List[Any] = []

    def enqueue(self, item: Any) -> None:
        self._inbox.append(item)

    def dequeue(self) -> Any:
        if not self._outbox:
            if not self._inbox:
                raise QueueEmptyError("dequeue from empty queue")
            while self._inbox:
                self._outbox.append(self._inbox.pop())
        return self._outbox.pop()

    def is_empty(self) -> bool:
        return not self._inbox and not self._outbox

    def size(self) -> int:
        return len(self._inbox) + len(self._outbox)

from typing import List

def bucket_sort(values: List[int]) -> List[int]:
    """Sort non-negative integers using bucket sort.

    Args:
        values: A list of non-negative integers.

    Returns:
        A new list sorted in non-decreasing order.

    Examples:
        >>> bucket_sort([29, 25, 3, 49, 9, 37, 21, 43])
        [3, 9, 21, 25, 29, 37, 43, 49]
        >>> bucket_sort([])
        []
    """
    if not isinstance(values, list):
        raise TypeError("values must be a list")
    if not values:
        return []
    if any(v < 0 for v in values):
        raise ValueError("bucket_sort only handles non-negative integers")
    if len(values) == 1:
        return list(values)
    lo, hi = min(values), max(values)
    if lo == hi:
        return list(values)
    bucket_count = len(values)
    buckets: List[List[int]] = [[] for _ in range(bucket_count)]
    for v in values:
        idx = (v - lo) * (bucket_count - 1) // (hi - lo)
        buckets[idx].append(v)
    out: List[int] = []
    for b in buckets:
        out.extend(sorted(b))
    return out

from typing import List

def binary_search(values: List[int], target: int) -> int:
    """Recursively search a sorted list for a target value.

    Args:
        values: A list sorted in ascending order.
        target: The value to locate.

    Returns:
        The index of target, or -1 if not found.

    Examples:
        >>> binary_search([1, 3, 5, 7, 9], 5)
        2
        >>> binary_search([1, 3, 5, 7, 9], 4)
        -1
        >>> binary_search([], 1)
        -1
    """
    if not isinstance(values, list):
        raise TypeError("values must be a list")
    return _binary_search(values, target, 0, len(values) - 1)

def _binary_search(values: List[int], target: int, lo: int, hi: int) -> int:
    if lo > hi:
        return -1
    mid = (lo + hi) // 2
    if values[mid] == target:
        return mid
    if values[mid] < target:
        return _binary_search(values, target, mid + 1, hi)
    return _binary_search(values, target, lo, mid - 1)

from typing import Dict, Optional

class _TrieNode:
    __slots__ = ("children", "is_word")
    def __init__(self) -> None:
        self.children: Dict[str, "_TrieNode"] = {}
        self.is_word: bool = False

class Trie:
    """A prefix tree for lowercase alphabetic words.

    Examples:
        >>> t = Trie()
        >>> t.insert("apple")
        >>> t.search("apple")
        True
        >>> t.search("app")
        False
        >>> t.starts_with("app")
        True
    """
    def __init__(self) -> None:
        self._root = _TrieNode()

    def insert(self, word: str) -> None:
        if not isinstance(word, str):
            raise TypeError("word must be a str")
        node = self._root
        for ch in word:
            node = node.children.setdefault(ch, _TrieNode())
        node.is_word = True

    def search(self, word: str) -> bool:
        node = self._find_node(word)
        return node is not None and node.is_word

    def starts_with(self, prefix: str) -> bool:
        return self._find_node(prefix) is not None

    def _find_node(self, s: str) -> Optional[_TrieNode]:
        if not isinstance(s, str):
            raise TypeError("input must be a str")
        node = self._root
        for ch in s:
            if ch not in node.children:
                return None
            node = node.children[ch]
        return node
